import { test, expect } from '@playwright/test';

test.describe('Async Form Submission', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/form-page'); // Replace with the actual form page URL
  });

  test('should disable submit button during async submission', async ({ page }) => {
    await page.fill(getByLabel('Name'), 'John Doe');
    await page.fill(getByLabel('Email'), 'john.doe@example.com');

    const submitButton = page.getByRole('button', { name: 'Submit' });
    await expect(submitButton).toBeEnabled();

    await submitButton.click();

    await expect(submitButton).toBeDisabled();

    // Simulate waiting for async operation to complete
    await page.waitForTimeout(2000); // Adjust timeout as necessary

    await expect(submitButton).toBeEnabled();
  });

  test('should show success message after successful submission', async ({ page }) => {
    await page.fill(getByLabel('Name'), 'Jane Doe');
    await page.fill(getByLabel('Email'), 'jane.doe@example.com');

    const submitButton = page.getByRole('button', { name: 'Submit' });
    await submitButton.click();

    await expect(submitButton).toBeDisabled();

    // Simulate waiting for async operation to complete
    await page.waitForTimeout(2000); // Adjust timeout as necessary

    await expect(page.getByText('Submission successful!')).toBeVisible();
  });
});
